mapper.select:
SELECT customer_id, MAX(create_time) as lastest_tracking_time
FROM dc_customer_tracking
WHERE del_flag = 0

    AND create_by = #{userId}


    AND YEAR(create_time) = #{year}


    AND MONTH(create_time) = #{month}


    AND DAY(create_time) = #{day}


    AND tracking_type = #{trackingType}


    AND cumtomer_status = #{customerStatus}


    AND is_return = #{isReturn}

GROUP BY customer_id

SELECT * FROM dc_customer_tracking WHERE del_flag = 0 AND tracking_time BETWEEN DATE_FORMAT(CURDATE(), '%Y-%m-01') AND LAST_DAY(CURDATE())
AND legal_support_id = #{legalSupportId}
AND remark2 = #{city}

SELECT * FROM dc_customer_tracking WHERE del_flag = 0 AND next_time >= CURDATE() AND next_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
AND legal_support_id = #{legalSupportId}
AND remark2 = #{city}
